{
  "name": "DEBYEFLEX 3003 X射线发生器",
  "name_en": "DEBYEFLEX 3003 X-ray generator",
  "manufacturer": "ISO",
  "description": "DEBYEFLEX 3003 是一台实验室用 X 射线发生器/管系统，可设置管电流和高压、控制快门并进行定时曝光。它通常作为 X 射线衍射及相关材料表征实验中的辐射源使用。",
  "description_en": "The DEBYEFLEX 3003 is a laboratory X-ray generator / tube system with controllable tube current, high voltage, shutter control, and timed exposure functions. It is typically used as an X-ray source for X-ray diffraction and related materials characterization experiments.",
  "tag_hints": [
    "X-ray source",
    "X-ray diffraction",
    "high-voltage control",
    "tube current control",
    "shutter control",
    "timed exposure",
    "materials characterization"
  ],
  "actions": [
    {
      "action_name": "auto-init",
      "description": "初始化设备通信。",
      "description_en": "Initialize communication with the device."
    },
    {
      "action_name": "auto-read",
      "description": "读取设备返回数据。",
      "description_en": "Read returned data from the device."
    },
    {
      "action_name": "auto-write",
      "description": "向设备发送原始命令。",
      "description_en": "Send a raw command to the device."
    },
    {
      "action_name": "auto-get_nominal_current",
      "description": "获取设定管电流。",
      "description_en": "Get the nominal tube current."
    },
    {
      "action_name": "auto-get_actual_current",
      "description": "获取实际管电流。",
      "description_en": "Get the actual tube current."
    },
    {
      "action_name": "auto-set_current",
      "description": "设置管电流。",
      "description_en": "Set the tube current."
    },
    {
      "action_name": "auto-get_nominal_voltage",
      "description": "获取设定高压。",
      "description_en": "Get the nominal high voltage."
    },
    {
      "action_name": "auto-get_actual_voltage",
      "description": "获取实际高压。",
      "description_en": "Get the actual high voltage."
    },
    {
      "action_name": "auto-set_voltage",
      "description": "设置高压。",
      "description_en": "Set the high voltage."
    },
    {
      "action_name": "auto-set_high_voltage_on",
      "description": "开启高压输出。",
      "description_en": "Turn on the high-voltage output."
    },
    {
      "action_name": "auto-set_high_voltage_off",
      "description": "关闭高压输出。",
      "description_en": "Turn off the high-voltage output."
    },
    {
      "action_name": "auto-open_shutter",
      "description": "打开快门。",
      "description_en": "Open the shutter."
    },
    {
      "action_name": "auto-close_shutter",
      "description": "关闭快门。",
      "description_en": "Close the shutter."
    },
    {
      "action_name": "auto-activate_timer",
      "description": "启用曝光定时器。",
      "description_en": "Activate the exposure timer."
    },
    {
      "action_name": "auto-deactivate_timer",
      "description": "停用曝光定时器。",
      "description_en": "Deactivate the exposure timer."
    },
    {
      "action_name": "auto-set_timer",
      "description": "设置曝光定时器时长。",
      "description_en": "Set the exposure timer duration."
    },
    {
      "action_name": "auto-get_actual_time",
      "description": "获取定时器当前时间。",
      "description_en": "Get the actual timer time."
    },
    {
      "action_name": "auto-get_nominal_time",
      "description": "获取定时器设定时间。",
      "description_en": "Get the nominal timer time."
    },
    {
      "action_name": "auto-lock_keyboard",
      "description": "锁定设备键盘。",
      "description_en": "Lock the device keyboard."
    },
    {
      "action_name": "auto-unlock_keyboard",
      "description": "解锁设备键盘。",
      "description_en": "Unlock the device keyboard."
    },
    {
      "action_name": "auto-get_status",
      "description": "获取选定的状态参数。",
      "description_en": "Get selected status parameters."
    }
  ]
}

